input.command:
mysql -u root metadata -e "SHOW TABLES;" 2>&1; mysql -u root metadata -e "
SELECT table_name FROM information_schema.tables WHERE table_schema='metadata' ORDER BY 1;
" 2>&1

mysql -u root metadata -e "
SELECT COUNT(*) AS event_ext_total FROM event_ext;
SELECT COUNT(*) AS raw_table_empty FROM event_ext WHERE raw_table_fqn IS NULL OR raw_table_fqn='';
SELECT COUNT(*) AS raw_table_filled FROM event_ext WHERE raw_table_fqn IS NOT NULL AND raw_table_fqn!='';
SELECT table_name FROM information_schema.tables WHERE table_schema='metadata' ORDER BY 1;
" 2>&1
